import { spawn } from 'node:child_process'

type ShOptions = { cwd?: string }
type ShResult = { stdout: string; stderr: string; code: number }

export class Shell {
  static sho = (cmd: string, args: string[], options: ShOptions = {}): Promise<string> =>
    Shell.sh(cmd, args, options).then((r) => r.stdout)

  static sh = (cmd: string, args: string[], options: ShOptions = {}): Promise<ShResult> => {
    // console.log(`${cmd} ${args.join(' ')}`)
    const proc = spawn(cmd, args, { stdio: 'pipe', env: process.env, ...options })
    const stdout: Buffer[] = []
    const stderr: Buffer[] = []
    proc.stdout.on('data', (data) => stdout.push(data))
    proc.stderr.on('data', (data) => stderr.push(data))

    const join = (buffers: Buffer[]) =>
      buffers
        .map((b) => b.toString('utf-8'))
        .join('')
        .trim()
    return new Promise<ShResult>((resolve, reject) => {
      proc.on('close', (code) => {
        if (code !== 0) reject(new Error(`${cmd} ${args.join(' ')} failed: ${join(stderr)}`))
        else resolve({ stdout: join(stdout), stderr: join(stderr), code })
      })
      proc.on('error', (error) => reject(error))
    })
  }
}
